function csAuthErr(e, es) {
  var m = (e && (e.message || e.error_description)) || '';
  if (/Invalid login/i.test(m)) return es ? 'Correo o contraseña incorrectos.' : 'Wrong email or password.';
  if (/already registered|already been registered/i.test(m)) return es ? 'Ese correo ya tiene cuenta. Inicia sesión.' : 'That email already has an account. Sign in instead.';
  if (/at least 6|Password should/i.test(m)) return es ? 'La contraseña debe tener al menos 6 caracteres.' : 'Password must be at least 6 characters.';
  if (/Email not confirmed/i.test(m)) return es ? 'Confirma tu correo: te enviamos un enlace.' : 'Please confirm your email: we sent you a link.';
  if (/valid email|invalid.*email/i.test(m)) return es ? 'Escribe un correo válido.' : 'Enter a valid email.';
  if (/rate limit|too many/i.test(m)) return es ? 'Demasiados intentos. Espera un momento.' : 'Too many attempts. Please wait a moment.';
  if (/provider is not enabled/i.test(m)) return es ? 'El inicio con Google aún no está activado.' : 'Google sign-in isn’t enabled yet.';
  if (/Failed to fetch|NetworkError|Load failed/i.test(m)) return es ? 'No hay conexión con el servidor. Prueba en la versión web.' : 'Can’t reach the server. Try the web version.';
  return m || (es ? 'Algo salió mal. Inténtalo de nuevo.' : 'Something went wrong. Please try again.');
}

