function initLang() { var ok = ['en','es','zh','tl','vi','fr','ko'], v = null; try { v = new URLSearchParams(location.search).get('lang'); } catch (e) {} if (ok.indexOf(v) < 0) { try { v = localStorage.getItem('cs_lang'); } catch (e) {} } return ok.indexOf(v) >= 0 ? v : 'en'; }
var LANGS = [['es','Español'],['en','English'],['zh','中文'],['tl','Tagalog'],['vi','Tiếng Việt'],['fr','Français'],['ko','한국어']];
function trS(s) {
  var d = I18N[CUR_LANG]; if (!d || typeof s !== 'string' || !s) return s;
  var m = s.match(/^(\s*)([\s\S]*?)(\s*)$/), core = m[2];
  if (!core) return s;
  if (d[core] != null) return m[1] + d[core] + m[3];
  var m2 = core.match(/^([^A-Za-z0-9À-ÿ¿¡“"(]+)([\s\S]+)$/);
  if (m2) { var c2 = m2[2].trim(); if (d[c2] != null) return m[1] + m2[1] + d[c2] + m[3]; }
  var m3 = core.match(/^([\s\S]+?)(\s*[▾▴…:]+)$/);
  if (m3 && d[m3[1]] != null) return m[1] + d[m3[1]] + m3[2] + m[3];
  if (core.indexOf(' · ') > 0) return m[1] + core.split(' · ').map(trS).join(' · ') + m[3];
  return s;
}
function LX(a, b) { return CUR_LANG === 'es' ? a : (CUR_LANG === 'en' ? b : trS(b)); }
var TR_SKIP = /style|Style|diag|Diag|cloud|Cloud|^key$|^id$|^d$|^pid$|^url$/;
function trTree(v) {
  if (typeof v === 'string') return trS(v);
  if (Array.isArray(v)) return v.map(trTree);
  if (v && typeof v === 'object' && Object.getPrototypeOf(v) === Object.prototype) { var o = {}; for (var k in v) o[k] = TR_SKIP.test(k) ? v[k] : trTree(v[k]); return o; }
  return v;
}
var LEARN = {
  start: { es: ['Tu instrumento y tu estilo', 'Primero cuéntame qué tocas y qué música te gusta. Con eso, todo lo demás se adapta a ti: el sonido, los dibujos de cómo se toca y los acordes que te recomiendo.', [
      ['¿Por qué importa el instrumento?', 'Un mismo acorde se toca distinto en cada instrumento. Si eliges guitarra, te muestro dónde poner los dedos en la guitarra; si eliges piano, qué teclas apretar. Y todo suena con ese instrumento.'],
      ['Piano', 'Puedes tocar el acorde completo con una mano y la nota grave con la otra. Sirve para casi todo: pop, baladas, jazz, gospel.'],
      ['Guitarra acústica', 'Puedes rasguear (pasar la mano por todas las cuerdas) o tocar las notas una a una. Es la de las fogatas, el folk y el pop tranquilo.'],
      ['Guitarra eléctrica', 'Limpia suena suave (funk, R&B). Con distorsión suena fuerte y rasposa (rock, metal); ahí se usan «power chords», acordes de solo dos notas.'],
      ['Flauta', 'Solo suena una nota a la vez, así que los acordes se tocan nota por nota, uno detrás de otro.'],
      ['Cuerdas (violín)', 'Notas largas que llenan el fondo y dan emoción, como en las películas.'],
      ['Sintetizador', 'Sonidos electrónicos: pop actual, lo-fi y música electrónica.'],
      ['¿Y el estilo?', 'Según el estilo te recomiendo otros acordes (más sofisticados en jazz, más simples y potentes en rock), otro ritmo, otra batería y canciones de ejemplo de ese estilo.']] ],
    en: ['Your instrument and your style', 'First tell me what you play and what music you like. Then everything adapts to you: the sound, the drawings of how to play, and the chords I recommend.', [
      ['Why does the instrument matter?', 'The same chord is played differently on each instrument. Pick guitar and I show where to put your fingers on the guitar; pick piano and I show which keys to press. And everything plays with that sound.'],
      ['Piano', 'You can play the whole chord with one hand and a low note with the other. Works for almost anything: pop, ballads, jazz, gospel.'],
      ['Acoustic guitar', 'You can strum (sweep your hand across all strings) or play the notes one by one. The campfire, folk and soft pop instrument.'],
      ['Electric guitar', 'Clean, it sounds smooth (funk, R&B). With distortion it sounds loud and gritty (rock, metal), where “power chords” of just two notes are used.'],
      ['Flute', 'Plays only one note at a time, so chords are played note by note, one after another.'],
      ['Strings (violin)', 'Long notes that fill the background and add emotion, like in movies.'],
      ['Synth', 'Electronic sounds: modern pop, lo-fi and electronic music.'],
      ['And the style?', 'Depending on your style I recommend different chords (fancier in jazz, simpler and stronger in rock), a different rhythm, drums and example songs.']] ],
    demo: 'inst' },
  mood: { es: ['¿Cómo quieres que suene?', 'Aquí eliges la emoción de tu canción. Los acordes que te recomiendo cambian según lo que elijas.', [
      ['La regla básica', 'Los acordes mayores suenan alegres y luminosos. Los menores suenan tristes o íntimos. Entre uno y otro solo cambia una nota. Escucha C y luego Cm.'],
      ['Alegre', 'Usa sobre todo acordes mayores y vuelve seguido a «casa». Ejemplo: C – G – Am – F.'],
      ['Melancólico', 'Empieza o se apoya en un acorde menor. Curioso: Am – F – C – G tiene los mismos acordes que el alegre, pero empezar en Am lo vuelve nostálgico.'],
      ['Épico', 'Acordes grandes que van subiendo, como en el cine: Am – F – G.'],
      ['Soñador', 'Acordes con una nota extra que queda «flotando» (como Cmaj7). Suena suave, como en un sueño.'],
      ['Tenso', 'Acordes que suenan a «algo va a pasar» y piden resolverse.'],
      ['Oscuro', 'Acordes menores con notas graves que van bajando, como Am – G – F – E.'],
      ['Cualquiera', 'Si eliges «Cualquiera», te recomiendo los acordes que mejor siguen a los tuyos, sin importar la emoción.']] ],
    en: ['How should it sound?', 'Here you choose your song’s emotion. The chords I recommend change based on what you pick.', [
      ['The basic rule', 'Major chords sound happy and bright. Minor chords sound sad or intimate. Only one note changes between them. Listen to C, then Cm.'],
      ['Happy', 'Mostly major chords that keep coming back “home”. Example: C – G – Am – F.'],
      ['Melancholic', 'Starts on or leans on a minor chord. Fun fact: Am – F – C – G has the same chords as the happy one, but starting on Am makes it nostalgic.'],
      ['Epic', 'Big chords climbing up, like in movies: Am – F – G.'],
      ['Dreamy', 'Chords with an extra note that “floats” (like Cmaj7). Soft, like a dream.'],
      ['Tense', 'Chords that sound like “something is about to happen” and want to resolve.'],
      ['Dark', 'Minor chords with low notes walking down, like Am – G – F – E.'],
      ['Any', 'Pick “Any” and I recommend whatever chords follow yours best, regardless of emotion.']] ],
    demo: 'mood' },
  cx: { es: ['¿Acordes simples o con más color?', 'Decide cuántas notas tienen los acordes que te recomiendo. Más notas = sonido más rico, pero más difícil de tocar.', [
      ['Simples (3 notas)', 'Los de toda la vida, como C = do, mi, sol. Perfectos para empezar, para rock, pop y folk.'],
      ['Sus y add', 'Cambian o añaden una nota (Csus4, Cadd9). Suenan abiertos y modernos.'],
      ['Sextas', 'C6: suena dulce y retro, como un bolero.'],
      ['Séptimas (4 notas)', 'Cmaj7 suena suave, C7 suena a «quiero moverme», Am7 suena relajado. Muy usados en R&B, jazz y bossa nova.'],
      ['Novenas y más', 'Acordes muy ricos y elegantes (Cmaj9, Am11). Neo-soul, gospel y jazz.'],
      ['Tus acordes', 'Al cambiar el nivel te pregunto si quieres convertir los acordes que ya tienes o usarlo solo para las nuevas recomendaciones.']] ],
    en: ['Simple chords or more color?', 'Decide how many notes the chords I recommend have. More notes = richer sound, but harder to play.', [
      ['Simple (3 notes)', 'The classics, like C = C, E, G. Perfect to start, and for rock, pop and folk.'],
      ['Sus and add', 'Change or add a note (Csus4, Cadd9). Open, modern sound.'],
      ['Sixths', 'C6: sweet and retro.'],
      ['Sevenths (4 notes)', 'Cmaj7 sounds soft, C7 sounds like “I want to move”, Am7 sounds relaxed. Common in R&B, jazz and bossa nova.'],
      ['Ninths and beyond', 'Very rich, elegant chords (Cmaj9, Am11). Neo-soul, gospel and jazz.'],
      ['Your chords', 'When you change the level, I ask whether to convert the chords you already have or use it only for new recommendations.']] ],
    demo: 'cx' },
  sur: { es: ['¿Quieres sorpresas?', 'Cada canción tiene una «familia» de 7 acordes que suenan bien juntos. Aquí decides si te recomiendo también acordes de fuera de esa familia.', [
      ['Ninguna', 'Solo acordes de la familia. Suena seguro y conocido.'],
      ['Algunas', 'De vez en cuando un acorde «prestado» que da un toque especial. Por ejemplo, en C mayor el Fm suena nostálgico, como en muchas baladas.'],
      ['Muchas', 'Acordes de fuera más seguido. Más sorpresa y personalidad, menos predecible.'],
      ['¿Por qué funcionan?', 'Un acorde de fuera suena bien si comparte notas con los de al lado o si te lleva de vuelta a un acorde de la familia.']] ],
    en: ['Want surprises?', 'Every song has a “family” of 7 chords that sound good together. Here you decide whether I also recommend chords from outside that family.', [
      ['None', 'Only family chords. Safe and familiar.'],
      ['Some', 'Now and then a “borrowed” chord that adds something special. In C major, Fm sounds nostalgic, like in many ballads.'],
      ['Lots', 'Outside chords more often. More surprise and personality, less predictable.'],
      ['Why do they work?', 'An outside chord sounds good if it shares notes with its neighbors or leads you back to a family chord.']] ],
    demo: 'sur' },
  count: { es: ['¿Cuántos acordes te propongo?', 'Elige si quieres ideas de un acorde o frases completas.', [
      ['1 acorde', 'Solo el siguiente paso. Ideal para construir poco a poco y escuchar cada cambio.'],
      ['2 o 4 acordes', 'Una frase completa que ya suena a canción. Útil para inventar una parte nueva, como el coro.']] ],
    en: ['How many chords should I suggest?', 'Choose single-chord ideas or full phrases.', [
      ['1 chord', 'Just the next step. Great for building little by little and hearing each change.'],
      ['2 or 4 chords', 'A full phrase that already sounds like a song. Useful for inventing a new section, like the chorus.']] ] },
  prog: { es: ['Tu progresión', 'Una progresión es la lista de acordes que se repite en tu canción. Es su esqueleto: la melodía y la letra van encima.', [
      ['Cómo empezar', 'Si ya tienes acordes, ponlos en orden con «Añadir acorde». Si no tienes ninguno, elige una progresión famosa de las ideas para empezar, o cualquier acorde que te guste: yo te ayudo con el resto.'],
      ['La tonalidad', 'Miro tus acordes y adivino en qué «tono» estás (por ejemplo, C mayor). Es como saber en qué barrio vive tu canción.'],
      ['Los números (I, IV, V…)', 'Indican qué lugar ocupa cada acorde en la familia. Mayúscula = mayor, minúscula = menor. Con números puedes tocar la misma progresión en cualquier tono.'],
      ['Casa, paseo y tensión', 'Cada acorde tiene un papel: el I es la casa (calma), el IV es salir a pasear (movimiento) y el V es la tensión que pide volver a casa.'],
      ['Cuánto dura cada acorde', 'Con − y + decides cuánto suena cada uno. Cambiar rápido da energía; cambiar lento da calma.']] ],
    en: ['Your progression', 'A progression is the list of chords that repeats in your song. It’s the skeleton: melody and lyrics go on top.', [
      ['How to start', 'If you already have chords, add them in order with “Add chord”. If you have none, pick a famous progression from the starting ideas, or any chord you like: I’ll help with the rest.'],
      ['The key', 'I look at your chords and figure out which “key” you’re in (e.g. C major). Think of it as the neighborhood your song lives in.'],
      ['The numbers (I, IV, V…)', 'They show each chord’s place in the family. Uppercase = major, lowercase = minor. With numbers you can play the same progression in any key.'],
      ['Home, journey and tension', 'Each chord has a role: I is home (calm), IV is going for a walk (movement) and V is tension that wants to go back home.'],
      ['How long each chord lasts', 'Use − and + to set how long each one plays. Fast changes add energy; slow changes add calm.']] ],
    demo: 'prog' },
  rhythm: { es: ['Ritmo y velocidad', 'El ritmo decide cómo suenan tus acordes en el tiempo: lento o rápido, suave o con golpe.', [
      ['Tempo (BPM)', 'Cuántos golpes por minuto. 70 = lento, como una balada. 120 = medio, como el pop. 170 = rápido, como el punk.'],
      ['Compás', '4/4 se cuenta 1-2-3-4 (casi todo el pop y rock). 3/4 se cuenta 1-2-3, como un vals. 6/8 se siente como un balanceo.'],
      ['Cómo se toca', 'El mismo acorde cambia mucho según el patrón: golpes parejos, notas sueltas (arpegio), golpes a contratiempo (reggae) o con swing (blues).'],
      ['Batería y bajo', 'Añaden el acompañamiento típico de tu estilo para que suene como una canción de verdad.']] ],
    en: ['Rhythm and speed', 'Rhythm decides how your chords sound over time: slow or fast, soft or punchy.', [
      ['Tempo (BPM)', 'Beats per minute. 70 = slow, like a ballad. 120 = medium, like pop. 170 = fast, like punk.'],
      ['Time signature', '4/4 counts 1-2-3-4 (most pop and rock). 3/4 counts 1-2-3, like a waltz. 6/8 feels like swaying.'],
      ['How it’s played', 'The same chord changes a lot with the pattern: even strums, single notes (arpeggio), off-beat hits (reggae) or swing (blues).'],
      ['Drums and bass', 'Add your style’s typical backing so it sounds like a real song.']] ] },
  sugs: { es: ['¿Qué acorde pongo después?', 'Te recomiendo acordes que suenan bien después de los tuyos, ordenados del que mejor encaja al que menos.', [
      ['Cómo los elijo', 'Busco cambios que tu oído ya conoce de mil canciones, como pasar de la tensión (V) a la casa (I).'],
      ['Tu emoción cuenta', 'Si elegiste Alegre, Melancólico, etc., subo los acordes que transmiten esa emoción y bajo los que no.'],
      ['El porcentaje', 'Qué tan bien encaja cada idea con tus acordes, tu emoción y tu estilo.'],
      ['Escucha antes de elegir', 'Pulsa ▶ para oír la idea unida a tus acordes y quédate con la que se parezca a lo que tienes en la cabeza.']] ],
    en: ['Which chord comes next?', 'I recommend chords that sound good after yours, ordered from best fit to least.', [
      ['How I pick them', 'I look for changes your ear already knows from a thousand songs, like going from tension (V) to home (I).'],
      ['Your emotion counts', 'If you chose Happy, Melancholic, etc., I push up the chords that carry that emotion and push down the rest.'],
      ['The percentage', 'How well each idea fits your chords, your emotion and your style.'],
      ['Listen before choosing', 'Press ▶ to hear the idea after your chords and keep the one closest to what’s in your head.']] ] },
  struct: { es: ['Arma tu canción', 'Una canción se arma con partes: unas se repiten y otras cambian para que no aburra.', [
      ['Verso', 'Cuenta la historia. Suele repetirse con distinta letra.'],
      ['Pre-coro', 'Sube la emoción para preparar el coro.'],
      ['Coro', 'La parte que todo el mundo canta y recuerda. Suele tener más energía.'],
      ['Puente', 'Un cambio de aire (otros acordes) antes del último coro.'],
      ['Cómo se usa aquí', 'Tu progresión es la parte A. Crea más partes (B, C…) y ordénalas: por ejemplo A A B A. Usa los atajos si no sabes por dónde empezar.']] ],
    en: ['Build your song', 'A song is built from parts: some repeat and some change so it doesn’t get boring.', [
      ['Verse', 'Tells the story. Usually repeats with different lyrics.'],
      ['Pre-chorus', 'Builds up emotion to prepare the chorus.'],
      ['Chorus', 'The part everyone sings and remembers. Usually more energy.'],
      ['Bridge', 'A change of scenery (other chords) before the last chorus.'],
      ['How to use it here', 'Your progression is part A. Create more parts (B, C…) and order them, e.g. A A B A. Use the shortcuts if you don’t know where to start.']] ] },
  songs: { es: ['Canciones que usan tus acordes', 'Escuchar tus acordes en canciones famosas te ayuda a entender cómo suenan y te da ideas.', [
      ['Mismos acordes, otra canción', 'Cientos de éxitos usan los mismos 4 acordes. Lo que las hace distintas es la melodía, el ritmo y el sonido.'],
      ['En otro tono', 'Una progresión puede sonar más aguda o más grave. Los números (I, V, vi…) no cambian; solo los nombres de los acordes.'],
      ['Tus acordes y los del compositor', 'Los acordes resaltados son los que tú pusiste; los punteados son los cambios que hizo el compositor.'],
      ['Cómo se toca', 'Abre «Cómo se toca» para ver el ritmo, el orden de los acordes y dónde poner los dedos.']] ],
    en: ['Songs that use your chords', 'Hearing your chords in famous songs helps you understand how they sound and gives you ideas.', [
      ['Same chords, different song', 'Hundreds of hits use the same 4 chords. Melody, rhythm and sound make them different.'],
      ['In another key', 'A progression can sound higher or lower. The numbers (I, V, vi…) stay the same; only chord names change.'],
      ['Your chords vs. the songwriter’s', 'Highlighted chords are the ones you entered; dashed ones are changes the songwriter made.'],
      ['How to play it', 'Open “How to play it” to see the rhythm, chord order and finger positions.']] ] },
  tools: { es: ['Las herramientas', 'Cada pestaña es una herramienta distinta. Puedes usarlas en cualquier orden:', [
      ['Generador de acordes', 'Pones tus acordes y te digo cuál puede venir después. Con «Analizar mi progresión» te explico por qué funciona.'],
      ['Enriquecer mis acordes', 'Convierte tus acordes en versiones con más color, sin cambiar la idea.'],
      ['Escalas para tu melodía', 'Qué notas puedes cantar o tocar encima de tus acordes sin que choquen.'],
      ['Cambiar de tonalidad', 'Cómo pasar a otro tono a mitad de canción sin que suene forzado.'],
      ['Diccionario', 'Busca cualquier acorde y mira cómo se toca.'],
      ['Afinador', 'Afina tu instrumento con el micrófono.'],
      ['Aprende desde cero', 'Siete lecciones cortas, desde la primera nota hasta entender los acordes.']] ],
    en: ['The tools', 'Each tab is a different tool. Use them in any order:', [
      ['Chord generator', 'Enter your chords and I tell you what can come next. “Analyze my progression” explains why it works.'],
      ['Enrich my chords', 'Turns your chords into more colorful versions without changing the idea.'],
      ['Scales for your melody', 'Which notes you can sing or play over your chords without clashing.'],
      ['Change key', 'How to move to another key mid-song without it sounding forced.'],
      ['Dictionary', 'Look up any chord and see how to play it.'],
      ['Tuner', 'Tune your instrument with the microphone.'],
      ['Learn from scratch', 'Seven short lessons, from your first note to understanding chords.']] ] },
  ana: { es: ['Analizar una progresión', 'Te explico cómo está hecha una progresión, como si la desarmáramos juntos.', [['Qué hace', 'Pones los acordes y te digo en qué tono están, qué papel cumple cada uno (casa, paseo o tensión) y si usa algún truco especial.'], ['Para qué sirve', 'Para entender por qué te gusta una canción y usar esos mismos trucos en las tuyas.']]],
    en: ['Analyze a progression', 'I explain how a progression is built, as if we took it apart together.', [['What it does', 'Enter chords and I tell you the key, each chord’s role (home, journey or tension) and any special tricks.'], ['Why', 'To understand why you like a song and use the same tricks in yours.']]] },
  scl: { es: ['Escalas para tu melodía', 'Una escala es el grupo de notas que puedes usar encima de tus acordes sin que choquen.', [['Mayor y menor', 'Las 7 notas del tono de tu canción. Sobre C – G – Am – F funciona la escala de C mayor.'], ['Pentatónica', 'Solo 5 notas, quitando las que pueden chocar: es casi imposible equivocarse. La favorita para solos.'], ['Modos', 'Son la misma escala empezando en otra nota. Cada uno tiene su propio «color».']]],
    en: ['Scales for your melody', 'A scale is the group of notes you can use over your chords without clashing.', [['Major and minor', 'The 7 notes of your song’s key. Over C – G – Am – F, the C major scale works.'], ['Pentatonic', 'Only 5 notes, leaving out the ones that can clash: almost impossible to go wrong. The favorite for solos.'], ['Modes', 'The same scale starting on another note. Each has its own “color”.']]] },
  rea: { es: ['Enriquecer tus acordes', 'Cambiar tus acordes por versiones con más color que encajan con la misma melodía.', [['Para qué', 'Para darle a tu canción otro aire: más jazz, más oscura o más emotiva.'], ['Cómo', 'Uso acordes que comparten notas con los tuyos, así la melodía sigue encajando. Por ejemplo, Am en lugar de C.']]],
    en: ['Enrich your chords', 'Swap your chords for more colorful versions that fit the same melody.', [['Why', 'To give your song a new feel: jazzier, darker or more emotional.'], ['How', 'I use chords that share notes with yours, so the melody still fits. For example, Am instead of C.']]] },
  mod: { es: ['Cambiar de tonalidad', 'Es cuando la canción «sube» a otro tono, como el clásico último coro que suena más alto y emocionante.', [['Acorde puente', 'Un acorde que pertenece a los dos tonos te lleva de uno a otro sin que se note.'], ['Anunciar el cambio', 'Tocar el acorde de tensión (V) del nuevo tono lo anuncia con fuerza.'], ['Tonos cercanos y lejanos', 'Los tonos vecinos comparten casi todas sus notas, así que el cambio es suave. Cuanto más lejos, más llamativo.']]],
    en: ['Change key', 'It’s when the song “lifts” into another key, like the classic last chorus that sounds higher and more exciting.', [['Bridge chord', 'A chord that belongs to both keys takes you from one to the other without it being noticed.'], ['Announce the change', 'Playing the new key’s tension chord (V) announces it strongly.'], ['Near and far keys', 'Neighboring keys share almost all their notes, so the change is smooth. The farther away, the more striking.']]] },
  dic: { es: ['Diccionario de acordes', 'Busca cualquier acorde y mira cómo se toca, o al revés: aprieta notas y te digo qué acorde es.', [['Cómo leer un nombre', 'La letra es la nota principal (C, D…). Lo que viene después es el tipo: m = menor, 7 = séptima, maj7 = séptima mayor, sus4 = suspendido.'], ['Varias posiciones', 'Un mismo acorde se puede tocar en varios lugares del mástil o del teclado. Elige el más cómodo para ti.']]],
    en: ['Chord dictionary', 'Look up any chord and see how to play it, or the other way around: press notes and I tell you which chord it is.', [['Reading a name', 'The letter is the main note (C, D…). What follows is the type: m = minor, 7 = seventh, maj7 = major seventh, sus4 = suspended.'], ['Several shapes', 'The same chord can be played in several places on the neck or keyboard. Pick the most comfortable for you.']]] },
  tun: { es: ['Afinador', 'Afinar es ajustar cada cuerda para que suene en su nota exacta.', [['Cómo funciona', 'El micrófono escucha la nota que tocas y te dice si está baja (aprieta la clavija) o alta (aflójala).'], ['La nota de referencia', 'Todo el mundo afina tomando como base el La (A) a 440 vibraciones por segundo.']]],
    en: ['Tuner', 'Tuning means adjusting each string so it plays its exact note.', [['How it works', 'The microphone listens to the note you play and tells you if it’s too low (tighten the peg) or too high (loosen it).'], ['The reference note', 'Everyone tunes from the same A, which vibrates 440 times per second.']]] },
  learn: { es: ['Aprende desde cero', 'Siete lecciones cortas. Cada una te explica algo, te deja escucharlo y termina con una pregunta.', [['Para quién', 'Para quien empieza: no necesitas saber nada de teoría.'], ['Tu guía', 'Lumen te acompaña en cada lección y celebra contigo cuando aciertas.']]],
    en: ['Learn from scratch', 'Seven short lessons. Each one explains something, lets you hear it and ends with a question.', [['For whom', 'For beginners: no theory needed.'], ['Your guide', 'Lumen walks you through every lesson and celebrates with you when you get it right.']]] }
};
var NAV_ORDER = ['gen', 'rea', 'scl', 'mod', 'dic', 'tun', 'learn'];
var NAV_TAB = { rea: ['Enriquecer mis acordes', 'Enrich my chords'], mod: ['Cambiar de tonalidad', 'Change key'], scl: ['Escalas para tu melodía', 'Scales for your melody'] };
