var SUR_TIP = ['Decide si la app puede sugerirte acordes que no pertenecen a tu tonalidad. «Ninguno»: solo de tu tono, suena seguro. «Alguno»: a veces uno prestado que da color. «Muchos»: más sorpresas.', 'Whether the app may suggest chords outside your key. “None”: only your key, safe. “Some”: a borrowed chord now and then. “Lots”: more surprises.'];
var COUNT_TIP = ['Cuántos acordes te propone cada sugerencia: 1 es el siguiente paso; 2 o 4 es una frase completa, útil para crear una parte nueva como el coro.', 'How many chords each suggestion gives you: 1 is the next step; 2 or 4 is a full phrase, useful for a new section like the chorus.'];
